package com.yongdrel.bulk_verification_service.application.service;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.yongdrel.bulk_verification_service.adapter.out.persistence.*; import com.yongdrel.bulk_verification_service.application.port.PaymentLookupPort; import com.yongdrel.bulk_verification_service.domain.model.ItemResult; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class BulkVerificationService{
 private static final int MAX_ITEMS=500; private final BatchRepository batches;private final ItemRepository items;private final PaymentLookupPort payments;private final ObjectMapper mapper;
 public BulkVerificationService(BatchRepository b,ItemRepository i,PaymentLookupPort p,ObjectMapper m){batches=b;items=i;payments=p;mapper=m;}
 @Transactional public VerificationBatchEntity submit(UUID tenant,UUID organizer,String key,MultipartFile input){if(tenant==null||organizer==null||key==null||key.isBlank()||input==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid batch request");Optional<VerificationBatchEntity> old=batches.findByTenantIdAndIdempotencyKey(tenant,key);if(old.isPresent())return old.get();List<String> refs=parse(input);if(refs.isEmpty()||refs.size()>MAX_ITEMS)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid batch size");VerificationBatchEntity batch=batches.save(new VerificationBatchEntity(tenant,organizer,key));Set<String> seen=new HashSet<>();for(String ref:refs){ItemResult result;PaymentLookupPort.PaymentMatch match=null;if(!valid(ref))result=ItemResult.INVALID;else if(!seen.add(ref))result=ItemResult.DUPLICATE;else{match=payments.find(ref,tenant);if(match==null)result=ItemResult.UNMATCHED;else if(!match.sourceAvailable())result=ItemResult.REVIEW_REQUIRED;else if(!tenant.equals(match.tenantId()))result=ItemResult.UNMATCHED;else result=match.eligibleForReview()?ItemResult.MATCHED:ItemResult.REVIEW_REQUIRED;}items.save(new VerificationItemEntity(batch.getId(),ref,result,match==null?null:match.paymentId()));}return batch;}
 @Transactional(readOnly=true) public List<VerificationItemEntity> results(UUID id,UUID tenant){VerificationBatchEntity b=batches.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Batch not found"));if(!tenant.equals(b.getTenantId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant mismatch");return items.findByBatchIdOrderByProcessedAtAsc(id);}
 private List<String> parse(MultipartFile f){try{String s=new String(f.getBytes(),StandardCharsets.UTF_8).trim();if(s.startsWith("["))return mapper.readValue(s,new TypeReference<>(){});return Arrays.stream(s.split("\\R")).map(String::trim).filter(x->!x.isBlank()).map(x->x.contains(",")?x.substring(0,x.indexOf(',')).trim():x).toList();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid CSV or JSON");}}
 private boolean valid(String x){return x.length()<=128&&x.matches("[A-Za-z0-9._:/-]+");}
}
